.ember-credit_copyright{float:none;display:block;clear:both}
}
@media only screen and (max-width: 360px) {
.title-404{font-size:150px!important}
.Header .description p,.showpageOf{display:none}
}
@media only screen and (max-width: 300px) {
#sidebar-wrapper{display:none}
.related-thumb{width:100%;float:none}
.archive .post h2,.index .post h2{line-height:29px!important;font-size:15px!important}
article{overflow:hidden}
#blog-pager{padding:0;margin:0}
.item #blog-pager{margin:0 0 15px}
.index .resumo span,.archive .resumo span,.blsm-author-box img,.breadcrumbs{display:none}
.blsm-author-box ul li a{padding:0;background:none}
.ops-404{font-size:20px!important}
.title-404{font-size:120px!important}
h1.post-title{font-size:17px}
.ember-social #social a{width:24px;height:24px;line-height:24px}
.ember-ember-top-menu,.ember-search-btn{display:none}
.blsm-post-share li{width:100%}
.comments .comments-content .comment-header{width:100%;float:none;clear:both;margin:0;padding:0;width:100%;float:none;clear:both;margin:0 0 0 -35px;padding:0}
}

#Header1 h1, #Header1 h1 a{font-weight: 800;font-size:40px;color: #222;}
.search-transition-wrap{display:none;background:rgba(20, 22, 24, 0.95);bottom:0;height:100%;left:0;position:fixed;right:0;top:0;width:100% !important;transition:0.1s;z-index:99999;}
.search-transition-wrap .search-transition-inner{padding:0 25%;position:absolute;text-align:center;top:50%;width:100%;border:none !important;box-sizing:border-box;}
.search-transition-wrap .searchform .input-group, .search-transition-wrap .woocommerce-product-search .input-group{border-bottom:1px solid #fff;padding:0 !important;}
.search-transition-wrap .searchform .form-control, .search-transition-wrap .woocommerce-product-search .form-control{background:none;border:none;font-size:20px;color:#FFF;height:50px;padding:0;}
.search-transition-wrap .searchform .form-control{width:100%;box-sizing:border-box;padding-right:60px;font-family: Poppins;font-size: 30px;}
.search-transition-wrap .input-group-btn button{position:absolute;right:0px;top:10px;border:0px;color:#fff;background:rgba(0,0,0,0);}
.search-transition-wrap .input-group-btn button:before{font-family:"Ionicons";content:"\f4a5";font-size:25px;padding:10px;}
.search-transition-wrap form > .input-group{position:relative;}
.search-transition-wrap .btn-mini-close{background:rgba(0, 0, 0, 0) none repeat scroll 0 0;border:medium none;color:#fff !important;font-size:35px;position:fixed;top:50px;right:50px;margin-right:0px;opacity:1;transition:0.4s;}
.search-transition-wrap .btn-mini-close:hover{cursor:pointer;}
