function emberFetchFeed(path, onSuccess, onError) {
  fetch(path).then(function (response) {
    if (!response.ok) throw new Error("HTTP " + response.status);
    return response.json();
  }).then(onSuccess).catch(onError || function () {});
}

function emberEntryUrl(entry) {
  for (var k = 0; k < entry.link.length; k++) {
    if (entry.link[k].rel === "alternate") return entry.link[k].href;
  }
  return "#";
}

function emberAttr(value) {
  return String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

// Swap the size segment of a Blogger image URL (s72-c, s1600, w400-h300-...)
// for the requested one; YouTube thumbs get the medium-quality variant
function emberResizeImage(url, size) {
  if (!url) return url;
  if (url.indexOf("img.youtube.com") > -1) {
    return url.replace("/hqdefault.jpg", "/mqdefault.jpg").replace("/default.jpg", "/mqdefault.jpg");
  }
  return url.replace(/\/(s|w)\d+[^\/]*\//, "/" + size + "/");
}

function emberEntryImage(entry, size) {
  var content = entry.content ? entry.content.$t : (entry.summary ? entry.summary.$t : "");
  var img = "";
  if (content.indexOf("//www.youtube.com/embed/") > -1 && entry.media$thumbnail) {
    img = entry.media$thumbnail.url;
  } else if (content.indexOf("<img") > -1) {
    // DOMParser documents are inert, so this never downloads the post's images
    var doc = new DOMParser().parseFromString(content, "text/html");
    var first = doc.querySelector("img");
    if (first) img = first.getAttribute("src") || "";
  }
  if (!img && entry.media$thumbnail) img = entry.media$thumbnail.url;
  if (!img) return no_image;
  return emberResizeImage(img, size);
}

function emberFormatShortDate(published) {
  return month_format[parseInt(published.substring(5, 7), 10)] + " " + published.substring(8, 10) + ", " + published.substring(0, 4);
}

var EMBER_NO_THUMB = "https://4.bp.blogspot.com/-wPwjv7-YYGY/Wc98wlDT8qI/AAAAAAAAAEE/mH8YkPl8qJAH9FMuFKcShQvXXYMmVyrIgCLcBGAs/s1600/notfound.png";

// ---- Main navigation: rebuild the flat LinkList into a nested menu ----
// Nesting depth is encoded with leading underscores in the link names
function initMainMenu() {
  var menu = document.getElementById("ember-menu");
  if (!menu) return;
  var linkList = menu.querySelector(".LinkList");
  if (!linkList) return;
  var html = "";
  var level = -1;
  linkList.querySelectorAll("ul li").forEach(function (li) {
    var link = li.querySelector("a");
    if (!link) return;
    var text = li.textContent;
    var depth = (text.match(/_/g) || []).length;
    if (depth > level) html += "<ul>";
    if (depth < level) {
      for (var k = 0; k < level - depth; k++) html += "</ul></li>";
    }
    html += "<li><a href='" + link.getAttribute("href") + "'>" + text.replace(/_/g, "") + "</a>";
    level = depth;
  });
  for (var k = 0; k <= level; k++) {
    html += "</ul>";
    if (k !== 0) html += "</li>";
  }
  linkList.innerHTML = html;
  var topMenu = linkList.querySelector("ul");
  if (topMenu) topMenu.id = "ember_menu";
  document.querySelectorAll("#ember_menu a").forEach(function (a) {
    var href = (a.getAttribute("href") || "").toLowerCase();
    if (href.indexOf("[mega menu]") !== -1) {
      a.classList.add("mega-link");
      a.setAttribute("href", "/search/label/" + a.textContent + "?&max-results=" + perPage);
    }
  });
  selectnav("ember_menu");
  menu.querySelectorAll("ul > li > ul").forEach(function (sub) {
    sub.parentElement.classList.add("hasSubmenu");
  });
  menu.querySelectorAll(".widget").forEach(function (w) { w.setAttribute("style", "display:block!important;"); });
}

// ---- Mega menus: [mega menu] links get a paged grid of label posts ----
function emberMegaItemHtml(entry) {
  var thumb = entry.media$thumbnail ? emberResizeImage(entry.media$thumbnail.url, "s400") : EMBER_NO_THUMB;
  var url = emberEntryUrl(entry);
  return '<div class="ember-mega-item col-sm-3"><div class="ember-m-thumb" style="background:url(\'' + thumb + '\')"><a aria-label="' + emberAttr(entry.title.$t) + '" class="linkcover" href="' + url + '"></a></div><div class="ember-text"><a href="' + url + '">' + entry.title.$t + "</a></div></div>";
}

function initMegaMenus() {
  document.querySelectorAll("#ember_menu a.mega-link").forEach(function (link) {
    var label = link.textContent;
    emberFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&max-results=4", function (data) {
      var item = link.closest("li");
      if (item) {
        item.classList.add("isMega");
        item.classList.add("hasSubmenu");
      }
      (data.feed.link || []).forEach(function (l) {
        if (l.rel === "alternate" && l.type === "text/html") link.setAttribute("href", l.href + "?&max-results=" + perPage);
      });
      if (!data.feed.entry) return;
      var total = parseInt(data.feed.openSearch$totalResults.$t, 10);
      var start = parseInt(data.feed.openSearch$startIndex.$t, 10);
      var perStage = parseInt(data.feed.openSearch$itemsPerPage.$t, 10);
      var stages = Math.ceil(total / perStage);
      var html = '<ul data-itemnums="' + perStage + '" data-label="' + label + '" data-start="' + start + '" data-stages="' + stages + '" data-cstage="1" data-tpst="' + total + '">' +
        '<div class="mega-nav"><a aria-label="Previous posts" class="mega-prev disable" href="javascript:;" role="button"><i aria-hidden="true" class="fa fa-arrow-left"></i></a><a aria-label="Next posts" class="mega-next" href="javascript:;" role="button"><i aria-hidden="true" class="fa fa-arrow-right"></i></a></div>' +
        '<div class="ember-mega-loading" style="display:none"><div class="ember-loading-inner"><div class="ember-thecube"><div class="ember-cube ember-c1"></div><div class="ember-cube ember-c2"></div><div class="ember-cube ember-c4"></div><div class="ember-cube ember-c3"></div></div></div></div>' +
        '<div class="mega-inner row">' + data.feed.entry.map(emberMegaItemHtml).join("") + "</div></ul>";
      link.insertAdjacentHTML("afterend", html);
      var mega = link.nextElementSibling;
      function loadStage(forward) {
        var startIndex = Number(mega.getAttribute("data-start"));
        var stage = Number(mega.getAttribute("data-cstage"));
        var perPageMega = Number(mega.getAttribute("data-itemnums"));
        var stageCount = Number(mega.getAttribute("data-stages"));
        if (forward ? stage >= stageCount : stage <= 1) return;
        var newStart = forward ? startIndex + perPageMega : startIndex - perPageMega;
        var newStage = forward ? stage + 1 : stage - 1;
        var loading = mega.querySelector(".ember-mega-loading");
        if (loading) loading.style.display = "block";
        function hideLoading() {
          setTimeout(function () { if (loading) loading.style.display = "none"; }, 300);
        }
        emberFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&start-index=" + newStart + "&max-results=" + perPageMega, function (page) {
          mega.setAttribute("data-start", newStart);
          mega.setAttribute("data-cstage", newStage);
          mega.querySelector(".mega-prev").classList.toggle("disable", newStage <= 1);
          mega.querySelector(".mega-next").classList.toggle("disable", newStage >= stageCount);
          if (page.feed.entry) mega.querySelector(".mega-inner").innerHTML = page.feed.entry.map(emberMegaItemHtml).join("");
          hideLoading();
        }, hideLoading);
      }
      mega.querySelector(".mega-prev").addEventListener("click", function () { loadStage(false); });
      mega.querySelector(".mega-next").addEventListener("click", function () { loadStage(true); });
    });
  });
}

// ---- FeaturedPost widget: use the post image as the card background ----
function initFeaturedPostWidget() {
  document.querySelectorAll(".FeaturedPost .post-summary").forEach(function (card) {
    var image = card.querySelector(".image");
    if (image && image.getAttribute("src")) {
      card.setAttribute("style", "background-image:url(" + emberResizeImage(image.getAttribute("src"), "s800") + ");");
    }
    card.insertAdjacentHTML("beforeend", "<div class='overlay'></div>");
  });
}

// ---- Index thumbnails: swap Blogger's tiny 72px thumbs for sized versions ----
function emberUpgradeThumb(value, size) {
  if (value.indexOf("hqdefault.jpg") > -1) return value.replace("/hqdefault.jpg", "/mqdefault.jpg");
  if (value.indexOf("default.jpg") > -1) return value.replace("/default.jpg", "/mqdefault.jpg");
  if (value.indexOf("/s72-c") > -1) return value.replace("/s72-c", "/" + size);
  if (value.indexOf("/w72-h72-p-nu") > -1) return value.replace("/w72-h72-p-nu", "/" + size);
  return value;
}

function initPostThumbnails() {
  // Server-rendered post cards carry full-size firstImageUrl originals;
  // swap them for right-sized variants before the browser fetches them
  document.querySelectorAll("img.ember-featured-wid").forEach(function (img) {
    var src = img.getAttribute("src");
    if (src) img.setAttribute("src", emberResizeImage(src, "s800"));
  });
  document.querySelectorAll("div.ember-featured-wid").forEach(function (div) {
    var style = div.getAttribute("style");
    if (style) div.setAttribute("style", emberResizeImage(style, "s800"));
  });
  document.querySelectorAll(".post-home-image .post-thumb a").forEach(function (a) {
    var style = a.getAttribute("style");
    if (style) a.setAttribute("style", emberUpgradeThumb(style, "s800"));
  });
  document.querySelectorAll(".PopularPosts ul li img").forEach(function (img) {
    var src = img.getAttribute("src");
    if (src) img.setAttribute("src", emberUpgradeThumb(src, "s400"));
  });
}

// ---- Move author bio, author social links and post ads into the article ----
function emberMoveWidgetContent(targetSelector, sourceSelector) {
  var target = document.querySelector(targetSelector);
  var source = document.querySelector(sourceSelector);
  if (!target || !source) return;
  target.insertAdjacentHTML("beforebegin", source.innerHTML);
  source.innerHTML = "";
}

function initPostInjections() {
  emberMoveWidgetContent('span[name="author-social"]', ".post-author-social .widget-content");
  emberMoveWidgetContent('span[name="author-post"]', ".post-author-widget .widget-content");
  emberMoveWidgetContent('a[name="ad-post-top"]', "#ember-advert-2 .widget-content");
  emberMoveWidgetContent('a[name="ad-post-bottom"]', "#ember-advert-3 .widget-content");
}

// ---- Featured slider (homepage, autoplay, one post per slide) ----
var emberMainSwiperReady = null;
function emberLoadMainSwiper() {
  if (!emberMainSwiperReady) {
    emberMainSwiperReady = new Promise(function (resolve) {
      var css = document.createElement("link");
      css.rel = "stylesheet";
      css.href = "https://cdn.jsdelivr.net/npm/swiper@11.1.14/swiper-bundle.min.css";
      css.media = "print";
      css.onload = function () { css.media = "all"; };
      document.head.appendChild(css);
      if (window.Swiper) { resolve(); return; }
      var js = document.createElement("script");
      js.src = "https://cdn.jsdelivr.net/npm/swiper@11.1.14/swiper-bundle.min.js";
      js.onload = resolve;
      document.head.appendChild(js);
    });
  }
  return emberMainSwiperReady;
}

var EMBER_SLIDER_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function initFeaturedSlider() {
  document.querySelectorAll(".ember_featured_widget .HTML .widget-content").forEach(function (content) {
    var marker = content.querySelector("object.emberslider");
    if (!marker) return;
    var wrapper = content.closest(".feturepostwidgetember");
    if (wrapper && getComputedStyle(wrapper).display === "none") return;
    var label = marker.getAttribute("data-label");
    var count = marker.getAttribute("data-count") || 5;
    emberFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&max-results=" + count, function (data) {
      var html = '<div class="ember-featured ember-mainslider swiper"><div class="swiper-wrapper">';
      if (data.feed.entry) {
        data.feed.entry.forEach(function (entry, index) {
          var url = emberEntryUrl(entry);
          var title = entry.title.$t;
          var author = entry.author[0].name.$t;
          var authorUrl = entry.author[0].uri ? entry.author[0].uri.$t : "#";
          var parts = entry.published.$t.split("T")[0].split("-");
          var date = " " + EMBER_SLIDER_MONTHS[parts[1] - 1] + " " + parts[2] + ", " + parts[0];
          var image = emberEntryImage(entry, index === 0 ? "s1200" : "s800");
          if (index === 0) {
            // first slide is the homepage LCP element
            var hero = new Image();
            hero.fetchPriority = "high";
            hero.src = image;
          }
          var excerpt = (entry.content ? entry.content.$t : "").replace(/<.*?>/gi, "").split(/\s+/).slice(0, 24).join(" ");
          html += '<div class="swiper-slide item"><div class="grid-item secondary col-md-12"><article class="hentry ember-article"><div class="ember-article-image"><div class="ember-post-image"><div class="ember-bgr"></div><a aria-label="' + emberAttr(title) + '" href="' + url + '"><div class="ember-featured-wid" style="background:url(' + image + ')"></div></a><div class="social share-links clearfix"><ul class="social-icons list-unstyled list-inline"><li class="social-item facebook"><a class="post_share_facebook facebook" href="https://www.facebook.com/sharer.php?u=' + url + '" onclick="javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=220,width=600\');return false;" title="facebook"><i class="fa fa-facebook"></i></a></li><li class="social-item twitter"><a class="product_share_twitter twitter" href="https://twitter.com/share?url=' + url + '" onclick="javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=260,width=600\');return false;" title="twitter"><i class="fa fa-twitter"></i></a></li></ul></div></div></div><div class="article-content"><div class="article-inwhite"><div class="entry-header clearfix"><h3 class="entry-title"><a href="' + url + '" title="' + emberAttr(title) + '">' + title + '</a></h3></div><div class="article-meta clearfix"><span class="byline"><i aria-hidden="true" class="ion-ios-person-outline"></i><span class="author vcard"><a class="url fn n" href="' + authorUrl + '">' + author + '</a></span></span><span class="posted-on"><i aria-hidden="true" class="ion-ios-clock-outline"></i><a href="' + url + '" rel="bookmark"><time class="entry-date published" datetime="' + entry.published.$t + '">' + date + '</time></a></span></div><div class="entry-content"><div>' + excerpt + '...</div></div><a class="btn-read" href="' + url + '">Read More</a></div></div></article></div></div>';
        });
      } else {
        html += '<style>.ember-empty-panel img{max-width: 600px; width:100%}.ember-empty-panel{text-align: center;}.ember-empty-text h3{font-weight: 600;font-size:18px;line-height: 24px;margin-bottom:50px;}</style><div class="swiper-slide"><div class="ember-empty-panel"><div class="ember-empty-thumb"><img alt="" src="' + EMBER_NO_THUMB + '"></div><div class="ember-empty-text"><h3>No posts found for label : "' + label + '". <br/> <span class="ember-small">You can disable this widget by removing all the widget content from layout tab.</span></h3></div></div></div>';
      }
      html += '</div><div class="swiper-button-prev"></div><div class="swiper-button-next"></div></div>';
      content.innerHTML = html;
      content.parentElement.classList.add("emberfeatured");
      content.parentElement.classList.add("embr");
      document.querySelectorAll(".ember_featured_widget").forEach(function (section) {
        section.classList.add("ember-implied");
        section.classList.remove("ember-initiate");
      });
      emberLoadMainSwiper().then(function () {
        new Swiper(content.querySelector(".ember-mainslider"), {
          loop: true,
          slidesPerView: 1,
          spaceBetween: 10,
          autoplay: { delay: 5000 },
          navigation: {
            nextEl: content.querySelector(".swiper-button-next"),
            prevEl: content.querySelector(".swiper-button-prev")
          }
        });
      });
    });
  });
}

// ---- Sidebar feed widgets: recent comments, recent posts, posts by tag ----
var EMBER_EMPTY_PANEL = '<style>.ember-empty-panel img{max-width: 600px; width:100%}.ember-empty-panel{text-align: center;}.ember-empty-text h3{font-weight: 600;font-size:18px;line-height: 24px;margin-bottom:50px;}.bgr{background: rgb(236,239,241);}.bgr{box-sizing: border-box;padding:5px 10px;}</style><div class="ember-empty-panel bgr"><div class="ember-empty-thumb"><img src="' + EMBER_NO_THUMB + '"></div><div class="ember-empty-text"><h3>{message} <br/></h3></div></div>';

function emberRecentItemHtml(entry) {
  var url = emberEntryUrl(entry);
  var image = emberEntryImage(entry, "s400");
  return '<div class="ember-recent-item"><a aria-label="' + emberAttr(entry.title.$t) + '" class="ember-recent-thumb" href="' + url + '" style="background:url(' + image + ') no-repeat center center;background-size: cover"><span class="ember-trap"></span></a><div class="ember-recent-content"><h3 class="ember-recent-title"><a href="' + url + '">' + entry.title.$t + '</a></h3><span class="ember-author">' + entry.author[0].name.$t + '</span><span class="ember-time">' + emberFormatShortDate(entry.published.$t) + "</span></div></div>";
}

function emberRenderRecentList(span, data, emptyMessage) {
  var html = '<div class="ember-recent">';
  if (data.feed.entry) html += data.feed.entry.map(emberRecentItemHtml).join("");
  else html += EMBER_EMPTY_PANEL.replace("{message}", emptyMessage);
  html += "</div>";
  span.parentElement.innerHTML = html;
}

function initSidebarFeedWidgets() {
  document.querySelectorAll(".ember-widetize .HTML .widget-content object.ember-recent").forEach(function (span) {
    emberFetchFeed("/feeds/posts/default?alt=json&max-results=" + span.getAttribute("data-num"), function (data) {
      emberRenderRecentList(span, data, "No Posts found!");
