  document.querySelectorAll(".ember-widetize .HTML .widget-content object.ember-tagswid").forEach(function (span) {
    emberFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(span.getAttribute("data-label")) + "?alt=json&max-results=" + span.getAttribute("data-num"), function (data) {
      emberRenderRecentList(span, data, "No Posts found!");
    });
  });
  document.querySelectorAll(".ember-widetize .HTML .widget-content object.ember-cmnt").forEach(function (span) {
    emberFetchFeed("/feeds/comments/default?alt=json&max-results=" + span.getAttribute("data-num"), function (data) {
      var html = '<div class="ember-comments">';
      if (data.feed.entry) {
        data.feed.entry.forEach(function (entry) {
          var url = emberEntryUrl(entry);
          var text = (entry.content ? entry.content.$t : "").replace(/<\S[^>]*>/g, "");
          if (text.length > 70) text = text.substring(0, 50) + "...";
          var author = entry.author[0].name.$t;
          var avatar = entry.author[0].gd$image.src;
          if (avatar.indexOf("img1.blogblog.com/img/blank.gif") > -1 || avatar.indexOf("img2.blogblog.com/img/b16-rounded.gif") > -1) avatar = "https://img1.blogblog.com/img/anon36.png";
          if (avatar.indexOf("//") === 0) avatar = "https:" + avatar;
          html += '<div class="ember-comment"><div class="ember-comment-profile"><img class="ember-comment-thumb" loading="lazy" src="' + avatar + '"/></div><a href="' + url + '">' + author + '</a><span>"' + text + '"</span></div>';
        });
      } else {
        html += EMBER_EMPTY_PANEL.replace("{message}", "No comments!");
      }
      html += '</div><div class="clear"></div>';
      span.parentElement.innerHTML = html;
    });
  });
}

