//
// Sidebar tabs (Tab [1] / Tab [2] / Tab [3]) - vanilla replacement for the tabslet plugin
function initSidebarTabs() {
  var container = document.getElementById("ember-sidebar-tabs");
  if (!container) return;
  if (!container.querySelector(".widget")) { container.remove(); return; }
  // Tab labels come from each tab section's widget heading
  [1, 2, 3].forEach(function (n) {
    var heading = container.querySelector("#tabside" + n + " .widget h2, #tabside" + n + " .widget .widget-title");
    var link = container.querySelector(".ember-sidebar-tab .item-" + n + " a");
    if (heading && link) link.textContent = heading.textContent;
    container.querySelectorAll("#tabside" + n + " .widget h2, #tabside" + n + " .widget .widget-title").forEach(function (h) { h.remove(); });
  });
  var tabs = Array.prototype.slice.call(container.querySelectorAll(".ember-sidebar-tab li"));
  var panels = Array.prototype.filter.call(container.children, function (el) { return el.tagName === "DIV"; });
  var nav = container.querySelector(".ember-sidebar-tab");
  if (nav) nav.setAttribute("role", "tablist");
  panels.forEach(function (panel) { panel.setAttribute("role", "tabpanel"); });
  function activate(index, animate) {
    tabs.forEach(function (li, i) {
      li.classList.toggle("active", i === index);
      var link = li.querySelector("a");
      if (link) link.setAttribute("aria-selected", i === index ? "true" : "false");
    });
    panels.forEach(function (panel, i) {
      panel.style.display = i === index ? "block" : "none";
      if (i === index && animate) panel.style.animation = "emberFadeIn .4s ease";
    });
  }
  tabs.forEach(function (li, i) {
    li.classList.add("ember-hide");
    li.setAttribute("role", "presentation");
    var link = li.querySelector("a");
    if (link) link.setAttribute("role", "tab");
    (link || li).addEventListener("click", function (e) {
      e.preventDefault();
      activate(i, true);
    });
  });
  activate(0, false);
}

// Comment system tabs (blogger / disqus / facebook) - vanilla replacement for the simplyTab plugin
function initCommentTabs() {
  if (typeof cmtal === "undefined" || !cmtal) {
    var placer = document.getElementById("ember-comment-placer");
    if (placer) placer.remove();
    return;
  }
  var bloggerTab = document.querySelector(".ember-blogger-comment");
  var comments = document.getElementById("comments");
  if (bloggerTab && comments) bloggerTab.appendChild(comments);
  document.querySelectorAll(".ember-tabs").forEach(function (tabs) {
    var panes = Array.prototype.filter.call(tabs.children, function (el) { return el.hasAttribute("data-tab"); });
    if (!panes.length) return;
    tabs.classList.add("simplyTab");
    var header = document.createElement("div");
    header.className = "ember-tabs-header";
    var wrapper = document.createElement("ul");
    wrapper.className = "ember-tab-wrapper";
    wrapper.setAttribute("role", "tablist");
    header.appendChild(wrapper);
    tabs.insertBefore(header, tabs.firstChild);
    var links = [];
    panes.forEach(function (pane, i) {
      pane.classList.add("content-tab");
      pane.setAttribute("role", "tabpanel");
      pane.style.display = i === 0 ? "block" : "none";
      var item = document.createElement("li");
      item.setAttribute("role", "presentation");
      var link = document.createElement("a");
      link.href = "#";
      link.textContent = pane.getAttribute("data-tab");
      link.setAttribute("role", "tab");
      link.setAttribute("aria-selected", i === 0 ? "true" : "false");
      if (i === 0) link.className = "activeTab";
      link.addEventListener("click", function (e) {
        e.preventDefault();
        links.forEach(function (el) {
          el.classList.remove("activeTab");
          el.setAttribute("aria-selected", "false");
        });
        link.classList.add("activeTab");
        link.setAttribute("aria-selected", "true");
        panes.forEach(function (p, j) {
          p.style.display = j === i ? "block" : "none";
          if (j === i) p.style.animation = "emberFadeIn .4s ease";
        });
      });
      links.push(link);
      item.appendChild(link);
      wrapper.appendChild(item);
    });
  });
}

