//
// ---- Homepage custom widgets: list and gallery layouts from label feeds ----
var emberSwiperReady = null;
function emberLoadSwiper() {
  if (!emberSwiperReady) {
    emberSwiperReady = new Promise(function (resolve) {
      var css = document.createElement("link");
      css.rel = "stylesheet";
      css.href = "https://cdn.jsdelivr.net/npm/swiper@11.1.14/swiper-bundle.min.css";
      // load without joining the critical request chain
      css.media = "print";
      css.onload = function () { css.media = "all"; };
      document.head.appendChild(css);
      var js = document.createElement("script");
      js.src = "https://cdn.jsdelivr.net/npm/swiper@11.1.14/swiper-bundle.min.js";
      js.onload = resolve;
      document.head.appendChild(js);
    });
  }
  return emberSwiperReady;
}

function emberExcerpt(html, wordCount) {
  return html.replace(/<.*?>/gi, "").split(/\s+/).slice(0, wordCount - 1).join(" ");
}

var EMBER_FULL_MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
function emberFormatLongDate(published) {
  var parts = published.split("T")[0].split("-");
  return " " + EMBER_FULL_MONTHS[parts[1] - 1] + " " + parts[2] + ", " + parts[0];
}

function emberNoPostsPanel(label) {
  return '<div class="ember-empty"><div class="ember-no-post"><div class="ember-entry-no-icon"><img class="ember-empty" alt="ember-empty" src="' + EMBER_NO_THUMB + '"></div><div class="ember-no-title"><h3 class="ember-postmatch">No posts matching tag "' + label + '".</h3></div></div></div>';
}

function emberShareIconsHtml(url) {
  return '<div class="ember-post-share"><div class="ember-cell"><ul class="social-icons list-unstyled list-inline"><li class="social-item facebook"> <a href="https://www.facebook.com/sharer.php?u=' + url + '" title="facebook" class="post_share_facebook facebook" onclick="javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=220,width=600\');return false;"> <i class="fa fa-facebook"></i> </a></li><li class="social-item twitter"> <a href="https://twitter.com/share?url=' + url + '" title="twitter" onclick="javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=260,width=600\');return false;" class="product_share_twitter twitter"> <i class="fa fa-twitter"></i> </a></li><li class="social-item pinterest"> <a href="https://pinterest.com/pin/create/button/?url=' + url + '" class="pinterest" title="pinterest" onclick="javascript:window.open(this.href,\'\', \'menubar=no,toolbar=no,resizable=yes,scrollbars=yes,height=600,width=600\');return false;"> <i class="fa fa-pinterest"></i> </a></li></ul></div></div>';
}

function emberRenderListWidget(widget, data) {
  var html = '<div class="ember-widget list">';
  if (data.feed.entry) {
    data.feed.entry.forEach(function (entry, index) {
      var url = emberEntryUrl(entry);
      var title = entry.title.$t;
      var author = entry.author[0].name.$t;
      var authorUrl = entry.author[0].uri ? entry.author[0].uri.$t : "#";
      var published = entry.published.$t;
      var date = emberFormatLongDate(published);
      var image = emberEntryImage(entry, index === 0 ? "s800" : "s400");
      var metaTime = '<span class="posted-on"><i class="ion-ios-clock-outline"></i><a href="' + url + '" rel="bookmark"><time class="entry-date published updated" datetime="' + published + '">' + date + "</time></a></span>";
      if (index === 0) {
        html += '<div class="ember-widget-col-1 ember-list-col"><article class="ember-post"><div class="ember-parentover"><div class="ember-list-media"><a href="' + url + '"><img alt="' + title + '" loading="lazy" src="' + image + '"></a>' + emberShareIconsHtml(url) + '</div><div class="ember-box-list"><div class="ember-box-inside"><div class="ember-list-content"><div class="entry-header"><h3 class="entry-title"><a href="' + url + '" rel="bookmark">' + title + '</a></h3></div></div><div class="article-meta"><span class="byline"><i class="ion-ios-person-outline"></i><span class="author vcard"><a class="url fn n" href="' + authorUrl + '">' + author + '</a></span></span> ' + metaTime + '</div><div class="entry-content"><div>' + emberExcerpt(entry.content ? entry.content.$t : "", 25) + '...</div><a class="btn-read" href="' + url + '">Read More</a></div></div></div></div></article></div><div class="ember-widget-col-2 ember-list-col">';
      } else {
        html += '<article class="ember-post"><div class="article-image"><div class="post-image"><a aria-label="' + emberAttr(title) + '" href="' + url + '" style="background:black url(' + image + ')" rel="bookmark"></a></div></div><div class="article-content side-item-text"><div class="entry-header"><div class="entry-header-title"><h3 class="entry-title"><a href="' + url + '" rel="bookmark">' + title + '</a></h3></div></div><div class="article-meta">' + metaTime + "</div></div></article>";
      }
    });
    html += '</div><div class="clearfix"></div></div>';
  } else {
    html += emberNoPostsPanel(widget.getAttribute("data-label")) + '<div class="clearfix"></div></div>';
  }
  widget.insertAdjacentHTML("beforeend", html);
}

function emberGalleryImage(entry) {
  if (!entry.media$thumbnail) return { id: "regular", img: EMBER_NO_THUMB };
  var url = entry.media$thumbnail.url;
  if (url.indexOf("img.youtube.com") > -1) {
    return { id: url.substr(url.indexOf("/vi/") + 4, 11), img: url.replace("/default.jpg", "/hqdefault.jpg") };
  }
  return { id: "regular", img: emberResizeImage(url, "s800") };
}

function emberRenderGalleryWidget(widget, data) {
  if (!data.feed.entry) {
    widget.insertAdjacentHTML("beforeend", '<div class="ember-widget gallery">' + emberNoPostsPanel(widget.getAttribute("data-label")) + "</div>");
    return;
  }
  var featureHtml = "";
  var slidesHtml = "";
  var state = "ntpl";
  data.feed.entry.forEach(function (entry, index) {
    var url = emberEntryUrl(entry);
    var title = entry.title.$t;
    var author = entry.author[0].name.$t;
    var authorUrl = entry.author[0].uri ? entry.author[0].uri.$t : "#";
    var published = entry.published.$t;
    var date = emberFormatLongDate(published);
    var media = emberGalleryImage(entry);
    if (index === 0) {
      featureHtml = '<div class="ember-gallery-feature"><div class="ember-iframe-hidden"></div><div class="feature-image  ' + media.id + '" data-vidid="' + media.id + '" style="background:url(' + media.img + ')"></div><div class="ember-absolutize"><div class="ember-dyn-t"><h3><a href="' + url + '">' + title + '</a></h3></div><div class="article-meta"><span class="byline"><i class="ion-ios-person-outline"></i><span class="author vcard"><a class="url fn n" href="' + authorUrl + '">' + author + '</a></span></span> <span class="posted-on"><i class="ion-ios-clock-outline"></i><a href="' + url + '" rel="bookmark"><time class="entry-date published updated" datetime="' + published + '">' + date + "</time></a></span></div></div></div>";
    }
    slidesHtml += '<div class="swiper-slide ember-gallery-post slide item dy-dn"><div class="' + state + " " + media.id + ' img_dyn getinfo" data-vidid="' + media.id + '" data-img="' + media.img + '" style="background:url(' + media.img + ')" data-auth="' + author + '" data-auth-uri="' + authorUrl + '" data-time="' + date + '"></div><div class="ember-slide-title"><h3><a href="' + url + '">' + title + "</a></h3></div></div>";
    if (index === 0) state = "playing";
  });
  widget.insertAdjacentHTML("beforeend",
    '<div class="ember-widget gallery">' + featureHtml + "</div>" +
    '<div class="ember-slider swiper"><div class="swiper-wrapper">' + slidesHtml + "</div></div>" +
    '<div class="swiper-button-prev"></div><div class="swiper-button-next"></div><div class="clearfix"></div>');
  var feature = widget.querySelector(".ember-gallery-feature");
  var featureImage = feature.querySelector(".feature-image");
  var iframeHolder = feature.querySelector(".ember-iframe-hidden");
  function playVideo(videoId) {
    iframeHolder.innerHTML = '<iframe src="https://www.youtube.com/embed/' + videoId + '?autoplay=1" allowfullscreen="" width="100%" height="400" frameborder="0"></iframe>';
    iframeHolder.style.display = "block";
    featureImage.style.display = "none";
  }
  featureImage.addEventListener("click", function () {
    var videoId = featureImage.getAttribute("data-vidid");
    if (videoId !== "regular") playVideo(videoId);
  });
  widget.querySelectorAll(".dy-dn.slide.ember-gallery-post").forEach(function (slide) {
    slide.addEventListener("click", function () {
      var info = slide.querySelector(".img_dyn.getinfo");
      widget.querySelectorAll(".ntpl").forEach(function (el) {
        el.classList.add("playing");
        el.classList.remove("ntpl");
      });
      info.classList.remove("playing");
      info.classList.add("ntpl");
      var authorLink = feature.querySelector(".author.vcard a");
      if (authorLink) {
        authorLink.setAttribute("href", info.getAttribute("data-auth-uri"));
        authorLink.textContent = info.getAttribute("data-auth");
      }
      var dynTitle = feature.querySelector(".ember-dyn-t");
      if (dynTitle) dynTitle.innerHTML = slide.querySelector(".ember-slide-title").innerHTML;
      var timeEl = feature.querySelector("time");
      if (timeEl) timeEl.textContent = info.getAttribute("data-time");
      var videoId = info.getAttribute("data-vidid");
      if (videoId !== "regular") {
        playVideo(videoId);
      } else {
        featureImage.setAttribute("style", "background:url(" + info.getAttribute("data-img") + ");");
        iframeHolder.innerHTML = "";
        iframeHolder.style.display = "none";
        featureImage.style.display = "block";
      }
    });
  });
  emberLoadSwiper().then(function () {
    new Swiper(widget.querySelector(".ember-slider"), {
      slidesPerView: 1,
      spaceBetween: 10,
      navigation: {
        nextEl: widget.querySelector(".swiper-button-next"),
        prevEl: widget.querySelector(".swiper-button-prev")
      },
      breakpoints: { 400: { slidesPerView: 2 }, 500: { slidesPerView: 3 }, 600: { slidesPerView: 4 } }
    });
  });
}

function initCustomWidgets() {
  document.querySelectorAll(".custwid .ember-widget").forEach(function (widget) {
    var label = widget.getAttribute("data-label");
    var type = (widget.getAttribute("data-type") || "").toLowerCase();
    emberFetchFeed("/feeds/posts/default/-/" + encodeURIComponent(label) + "?alt=json&max-results=5", function (data) {
      (data.feed.link || []).forEach(function (l) {
        if (l.rel === "alternate") {
          var widgetBox = widget.closest(".widget");
          var heading = widgetBox ? widgetBox.querySelector("h2.title") : null;
          if (heading) heading.insertAdjacentHTML("afterend", '<div class="ember-right-all"><a href="' + l.href + "?&max-results=" + perPage + '" >view all <i class="fa fa-arrow-right"></i></a></div>');
        }
      });
      if (type === "list") emberRenderListWidget(widget, data);
      else if (type === "gallery") emberRenderGalleryWidget(widget, data);
    });
  });
}

initCustomWidgets();
